147	    public void finishInitializingFirstPart() {
148	        if (finishedFirst) return;
149	
150	        Overload ol;
151	        for (int i = 0; i < pendingOverloads.size(); i++) {
152	            // Cannot be an iterator -- will get comodification exception
153	            // iteration to the growing end is perfectly ok.
154	            ol = pendingOverloads.get(i);
155	            SingleFcn sfcn = ol.getFn();
156	
157	            String ps = ol.ps != null ? String.valueOf(ol.ps) + " " : "";
158	
159	            if (sfcn instanceof FunctionClosure) {
160	                FunctionClosure cl = (FunctionClosure) sfcn;
161	                if (!cl.getFinished()) cl.finishInitializing();
162	
163	                if (debug) {
164	                    System.err.println("Overload " + ps + cl);
165	                }
166	
167	            } else if (sfcn instanceof Constructor) {
168	                Constructor cl = (Constructor) sfcn;
169	                if (!cl.getFinished()) cl.finishInitializing();
170	
171	                if (debug) {
172	                    System.err.println("Overload " + ps + cl);
173	                }
174	
175	            } else if (sfcn instanceof GenericConstructor) {
176	                if (debug) {
177	                    System.err.println("Overload " + ps + sfcn);
178	                }
179	
180	            } else if (sfcn instanceof Dummy_fcn) {
181	                if (debug) System.err.println("Overload primitive " + ps + sfcn);
182	
183	            } else if (sfcn instanceof FGenericFunction) {
184	                if (debug) System.err.println("Overload generic " + ps + sfcn);
185	
186	            } else {
187	                bug(errorMsg("Expected a closure or primitive, instead got ", sfcn));
188	            }
189	
190	            if (ol.ps != null) ol.ps.close();
191	        }
192	        finishedFirst = true;
193	    }
