223	                } else {
224	                    change = true;
225	                    new_overloads.add(overload);
226	                    allOverloadsEver.put(overload, overload);
227	                }
228	            }
229	
230	            if (new_overloads.size() == 0) {
231	                bless();
232	                return change;
233	            }
234	
235	            new_overloads.addAll(overloads);
236	
237	            // Put shorter parameter lists first (it's a funny sort order).
238	            // TODO I don't understand what's "unchecked" about the next line.
