368	                // (see sort order above)
369	                // possibilities
370	                // rest1 l2 can be no smaller than l1-1; iterate to l2
371	                // rest2 test out to l1
372	                // both  test out to l1
373	                // neither = required
374	
375	
376	                if (rest2) {
377	                    // both, rest2
378	                    min = l1;
379	                } else if (rest1) {
380	                    // rest1
381	                    if (l2 < l1 - 1) return;
382	                    min = l2;
383	                } else {
384	                    // neither
385	                    if (l1 != l2) return;
386	                    min = l1;
387	                }
388	
389	                //    if (!do_continue) {
390	
391	
392	                //                  int p1better = -1; // set to index where p1 is subtype
393	                //                  int p2better = -1; // set to index where p2 is subtype
394	
395	                //                  boolean distinct = false; // known to exclude
396	                //                  int unrelated = -1; // neither subtype nor exclude nor identical
397	                //                  boolean unequal = false;
398	                //                  boolean sawSymbolic1 = false;
399	                //                  boolean sawSymbolic2 = false;
400	                //                  int selfIndex = -1;
401	
402	                /* This is a hack for dealing with cases like
403	                *
404	  trait Bar[\A,nat n\]
405	      get():ZZ32 = n
406	  end
407	
408	  object Baz[\A,nat n\]() extends Bar[\A,n\]
409	  end
410	
411	  f[\A\](x:Bar[\A,17\]) = 20
412	  g[\A\](x:Baz[\A,17\]) = 21
413	  h[\A\](x:Bar[\A,17\]) = 22
414	  h[\A\](x:Baz[\A,17\]) = 23
415	
416	
417	
418	                */
419	                //                  boolean allObjInstance1 = true;
420	                //                  boolean allObjInstance2 = true;
421	
422	                /* Two own generics: each parameter type of o2 is also read over o2's own instances, its
423	                   static parameters apart from o1's (apart, made on first need). */
424	                boolean ownPair = ownGeneric(o1.getFn()) && ownGeneric(o2.getFn());
425	                Apart apart = null;
426	
427	                exclDumpln("Checking exclusion of ", pl1, " and ", pl2, ":");
428	                for (int k = 0; k < min; k++) {
429	                    FType p1 = pl1.get(k);
430	                    FType p2 = k < l2 ? pl2.get(k) : pl2.get(l2 - 1);
431	                    exclDump(k, ": ", p1, " and ", p2, ", ", p1.getExtends(), " and ", p2.getExtends(), ", ");
432	
433	                    p1 = deRest(p1);
434	                    p2 = deRest(p2);
435	
436	                    if (p1 == p2 && !p1.isSymbolic() && !p2.isSymbolic()) {
437	                        exclDumpln("equal.");
438	                        continue;
439	                    }
440	
441	                    /* Instances of one generic type whose static arguments may be equal: no object type for
442	                       the shortcut below, which takes two object types to exclude. */
443	                    boolean coincide = ownPair && instancesMayCoincide(p1, p2);
444	
445	                    allObjInstance1 &= p1 instanceof FTypeObject && !coincide;
446	                    allObjInstance2 &= p2 instanceof FTypeObject && !coincide;
447	
448	                    unequal = true;
449	
450	                    if (o1.getSelfParameterIndex() == k && o1.getSelfParameterIndex() == o2.getSelfParameterIndex()) {
451	                        exclDumpln("self params.");
452	                        // ONLY set this when the self indices coincide -- otherwise, they obey the same rules.
453	                        selfIndex = k;
454	                        /*
455	                        * Somebody Else's Problem -- if self parameters are different,
456	                        * any problems will be flagged at the object level.
457	                        */
458	                        if (!p1.equals(p2)) distinct = true; // This seems wrong/unnecessary
459	                    }
460	
461	                    if ( o1.getFn().getFnName() instanceof Op &&
462	                         o2.getFn().getFnName() instanceof Op &&
463	                         ((Op)o1.getFn().getFnName()).getFixity() !=
464	                         ((Op)o2.getFn().getFnName()).getFixity() )
465	                        distinct = true;
466	
467	                    boolean excludes = p1.excludesOther(p2);
468	                    /* Read at one instantiation of both, two own generics' parameter types can exclude where
469	                       instances of each do not: the exclusion is withdrawn there. */
470	                    boolean withdrawnHere = false;
471	                    if (excludes && ownPair) {
472	                        if (apart == null) apart = Apart.of(o1, o2);
473	                        List<FType> d = apart.domain;
474	                        withdrawnHere = !excludesOverInstances(p1, deRest(k < l2 ? d.get(k) : d.get(l2 - 1)), apart);
475	                    }
476	                    if (withdrawnHere) {
477	                        exclDumpln("not distinct over the instances of each.");
478	                        excludes = false;
479	                        withdrawn = true;
480	                    }
481	                    if (excludes) {
482	                        exclDumpln("distinct.");
483	                        distinct = true;
484	                    } else {
485	
486	                        boolean local_unrelated = true;
487	                        // Check for subtype constraint.
488	                        boolean p1subp2 = p1.subtypeOf(p2);
489	                        boolean p2subp1 = p2.subtypeOf(p1);
490	                        if (p1subp2 && !p2subp1) {
491	                            p1better = k;
492	                            local_unrelated = false;
493	                            exclDumpln(" left better.");
494	                        } else if (p2subp1 && !p1subp2) {
495	                            p2better = k;
496	                            local_unrelated = false;
497	                            exclDumpln(" right better.");
498	                        } else if (selfIndex != k) {
499	                            if (p1.isSymbolic() || withdrawnHere) sawSymbolic1 = true;
500	
501	                            if (p2.isSymbolic() || withdrawnHere) sawSymbolic2 = true;
502	                        }
503	                        if (local_unrelated && unrelated == -1) {
504	                            // Here we check for self parameters!
505	                            if (selfIndex != k) {
506	                                unrelated = k;
507	                                exclDumpln("Unrelated.");
508	                            }
509	                        }
510	                    }
511	                }
512	
513	                distinct |= unequal && (allObjInstance1 || allObjInstance2);
514	            }
515	            //      }
516	
517	            if (!distinct) {
518	                if (p1better >= 0 && p2better >= 0) {
519	                    meetOk = meetExistsIn(o1, o2, new_overloads);
520	                } else {
521	                    FType r1 = o1.getFn().getRange();
522	                    FType r2 = o2.getFn().getRange();
523	                    if (p1better >= 0) {
524	                        // subtype rule applies
525	                        result1Subtype2Failure = !r1.subtypeOf(r2);
526	                    } else if (p2better >= 0) {
527	                        // subtype rule applies
528	                        result2Subtype1Failure = !r2.subtypeOf(r1);
529	                    }
530	                }
531	            }
532	
533	
534	            if (!distinct && !overloadOk()) {
535	                if (validOnDeclaredDomains(o1, o2, new_overloads, withdrawn)) return;
536	                if (unrelated != -1 && !sawSymbolic1 && !sawSymbolic2 && overlapCovered(o1, pl1, o2, pl2, new_overloads)) return;
537	            }
538	
539	            describeOverloadingFailure(o1, o2, within, pl1, pl2);
540	
541	            return;
542	        }
