565	        private void describeOverloadingFailure(Overload o1,
566	                                                Overload o2,
567	                                                Environment within,
568	                                                List<FType> pl1,
569	                                                List<FType> pl2) {
570	            if (distinct) return;
571	            //OverloadComparisonResult ocr = this;
572	            if (sawSymbolic1 || sawSymbolic2) {
573	                exclDumpSkip();
574	                String explanation;
575	                if (sawSymbolic1 && sawSymbolic2) explanation = errorMsg("\n", o1, " and\n", o2, " have parameters\n");
576	                else if (sawSymbolic1) explanation = errorMsg("\n", o1, " has a parameter\n");
577	                else explanation = errorMsg("\n", o2, " has a parameter\n");
578	                explanation =
579	                        explanation + "with generic type, at least one pair of parameters must have excluding types";
580	                error(o1, o2, within, explanation);
581	            }
582	
583	            if (unrelated != -1) {
584	                exclDumpSkip();
585	                String s1 = parameterName(unrelated, o1);
586	                String s2 = parameterName(unrelated, o2);
587	
588	                String explanation = errorMsg(Ordinal.ordinal(unrelated + 1),
589	                                              " parameters ",
590	                                              s1,
591	                                              ":",
592	                                              pl1,
593	                                              " and ",
594	                                              s2,
595	                                              ":",
596	                                              pl2,
597	                                              " are unrelated (neither subtype, excludes, nor equal) and no excluding pair is present");
598	                error(o1, o2, within, explanation);
599	            }
600	
601	            if (p1better >= 0 && p2better >= 0 && !meetOk) {
602	                exclDumpSkip();
603	                error(o1, o2, within, errorMsg("Overloading of\n\t(first) ",
604	                                               o1,
605	                                               " and\n\t(second) ",
606	                                               o2,
607	                                               " fails because\n\t",
608	                                               formatParameterComparison(p1better, o1, o2, "more"),
609	                                               " but\n\t",
610	                                               formatParameterComparison(p2better, o1, o2, "less")));
611	            }
612	            if (p1better < 0 && p2better < 0 && selfIndex < 0) {
613	                exclDumpSkip();
614	                String explanation = null;
615	                if (l1 == l2 && rest1 == rest2) {
616	                    if (unequal) explanation = errorMsg("Overloading of ",
617	                                                        o1,
618	                                                        " and ",
619	                                                        o2,
620	                                                        " fails because their parameter lists have potentially overlapping (non-excluding) types");
621	                    else explanation = errorMsg("Overloading of ",
622	                                                o1,
623	                                                " and ",
624	                                                o2,
625	                                                " fails because their parameter lists have the same types");
626	                } else explanation = errorMsg("Overloading of ",
627	                                              o1,
628	                                              " and ",
629	                                              o2,
630	                                              " fails because of ambiguity in overlapping rest (...) parameters");
631	                error(o1, o2, within, explanation);
632	            }
633	
634	            if (result1Subtype2Failure) {
635	                String explanation = errorMsg("Overloading of ",
636	                                              o1,
637	                                              " and ",
638	                                              o2,
639	                                              " fails because the first parameter list is a subtype of the second, but the first result is not a subtype of the second");
640	                // System.err.println("FAIL " + explanation);
