658	     * keyword, is declared with a type parameter of its own whose bound is
659	     * written Any, as T extends Any; a type parameter without an extends
660	     * clause does not count.
661	     */
662	    static private boolean singleParameterBoundAny(Overload o) {
663	        if (o instanceof Overload.MethodOverload || o.getSelfParameterIndex() >= 0) return false;
664	        SingleFcn f = o.getFn();
665	        if (!(f instanceof GenericFunctionOrMethod)) return false;
666	        GenericFunctionOrMethod g = (GenericFunctionOrMethod) f;
667	        List<Param> ps = g.getParams();
668	        if (ps.size() != 1) return false;
669	        Param p = ps.get(0);

670	        if (NodeUtil.isVarargsParam(p) || p.getDefaultExpr().isSome() || p.getIdType().isNone()) return false;
671	        Type ty = NodeUtil.optTypeOrPatternToType(p.getIdType()).unwrap();
672	        if (!(ty instanceof VarType)) return false;
673	        String v = NodeUtil.nameString(((VarType) ty).getName());
674	        for (StaticParam sp : g.getStaticParams()) {
675	            if (!NodeUtil.isTypeParam(sp) || !NodeUtil.getName(sp).equals(v)) continue;
676	            for (BaseType b : sp.getExtendsClause()) {
677	                if (b instanceof AnyType) return true;
678	            }
679	        }
680	        return false;
681	    }
