747	    /**
748	     * A pair of one own generic and one declaration without static
749	     * parameters that the parameter-by-parameter check refuses, read on the
750	     * two declared domains: valid when one lies strictly inside the other and
751	     * the inner one's return type is below the outer one's for every
752	     * instance of the generic, its type parameters standing for themselves;
753	     * or when neither lies inside the other and declarations below both
754	     * cover their overlap (genericOverlapCovered).  Pairs of two generics
755	     * keep that check, except two own generics some pair of whose parameter
756	     * types excluded only when the two were read at one instantiation
757	     * (withdrawn), which are read on their declared domains, each over its
758	     * own instances (genericPairValid).
759	     */
760	    static private boolean validOnDeclaredDomains(Overload o1, Overload o2, Collection<Overload> all,
761	                                                  boolean withdrawn) {
762	        SingleFcn f1 = o1.getFn();
763	        SingleFcn f2 = o2.getFn();
764	        if (ownGeneric(f1) && ownGeneric(f2)) return withdrawn && genericPairValid(o1, o2, all);
765	        Overload gen;
766	        Overload plain;
767	        if (ownGeneric(f1) && !(f2 instanceof GenericFunctionOrMethod)) {
768	            gen = o1;
769	            plain = o2;
770	        } else if (ownGeneric(f2) && !(f1 instanceof GenericFunctionOrMethod)) {
771	            gen = o2;
772	            plain = o1;
773	        } else {
774	            return false;
775	        }
776	        if (hasRest(gen.getParams()) || hasRest(plain.getParams())) return false;
777	        if (gen.getParams().size() != plain.getParams().size()) return false;
778	        try {
779	            SingleFcn g = gen.getFn();
780	            SingleFcn p = plain.getFn();
781	            boolean plainInside = instanceHolding(g, plain.getParams(), true) != null;
782	            boolean genInside = declaredBelow(g, null, p, p, true);
783	            if (plainInside && genInside) return false;
784	            if (plainInside) return p.getRange().subtypeOf(g.getRange());
785	            if (genInside) return g.getRange().subtypeOf(p.getRange());
786	            return genericOverlapCovered(gen, plain, all);
787	        }
788	        catch (FortressException ex) {
789	            return false;
790	        }
791	    }
