793	    /**
794	     * Two own generics read on their declared domains, each over its own
795	     * instances: refused where each lies inside the other (the No
796	     * Duplicates Rule); valid where one lies inside the other and its return
797	     * type is below the other's at the instance that holds it (the Return
798	     * Type Rule); otherwise valid where a third declaration below both holds
799	     * their overlap (genericMeetCovered, the Meet Rule).
800	     */
801	    static private boolean genericPairValid(Overload o1, Overload o2, Collection<Overload> all) {
802	        List<FType> d1 = o1.getParams();
803	        List<FType> d2 = o2.getParams();
804	        if (hasRest(d1) || hasRest(d2) || d1.size() != d2.size()) return false;
805	        SingleFcn f = o1.getFn();
806	        SingleFcn g = o2.getFn();
807	        try {
808	            SingleFcn gHolding = instanceHolding(g, d1, true);
809	            SingleFcn fHolding = instanceHolding(f, d2, true);
810	            if (gHolding != null && fHolding != null) return false;
811	            if (gHolding != null) return f.getRange().subtypeOf(gHolding.getRange());
812	            if (fHolding != null) return g.getRange().subtypeOf(fHolding.getRange());
813	            return genericMeetCovered(o1, o2, all);
814	        }
815	        catch (FortressException ex) {
816	            return false;
817	        }
818	    }
