820	    /**
821	     * The overlap of two own generic functions f (o1) and g (o2), neither
822	     * inside the other, is held by a third declaration whose declared domain
823	     * lies inside both.  The overlap is read where the two declared domains,
824	     * each over its own static parameters (Apart), match position by
825	     * position (matchApart): static parameters that match a type that is no
826	     * static parameter become that type, and type parameters that match each
827	     * other become one type parameter made afresh (meetParams), below the
828	     * bounds of each, read as createSymbolicInstantiation reads them; the
829	     * overlap is f's domain at those static arguments, where g holds it.
830	     * Domains that do not match so, and declarations with a where clause,
831	     * are not read: such a pair is refused.
832	     */
833	    static private boolean genericMeetCovered(Overload o1, Overload o2, Collection<Overload> all) {
834	        if (!(o1.getFn() instanceof FGenericFunction) || !(o2.getFn() instanceof FGenericFunction)) return false;
835	        FGenericFunction f = (FGenericFunction) o1.getFn();
836	        FGenericFunction g = (FGenericFunction) o2.getFn();
837	        if (NodeUtil.getWhereClause(f.getFnDecl()).isSome() || NodeUtil.getWhereClause(g.getFnDecl()).isSome()) {
838	            return false;
839	        }
840	        Apart apart = Apart.of(o1, o2);
841	        List<FType> fArgs = GenericFunctionOrMethod.FunctionsAndState.symbolicStaticsByPartition.get(f);
842	        List<FType> gArgs = apart.fresh != null ? apart.fresh :
843	                            GenericFunctionOrMethod.FunctionsAndState.symbolicStaticsByPartition.get(g);
844	        List<FType> d1 = o1.getParams();
845	        List<FType> d2 = apart.domain;
846	        if (fArgs == null || gArgs == null || d2.size() != d1.size()) return false;
847	        if (fArgs.size() != f.getStaticParams().size() || gArgs.size() != g.getStaticParams().size()) return false;
848	        Map<FType, FType> parent = new IdentityHashMap<FType, FType>();
849	        for (int k = 0; k < d1.size(); k++) {
850	            if (!matchApart(deRest(d1.get(k)), deRest(d2.get(k)), parent)) return false;
851	        }
852	        try {
853	            List<FType> meetArgs = meetParams(f, fArgs, g, gArgs, parent, o1, o2);
854	            if (meetArgs == null) return false;
855	            List<FType> meet = f.typeApply(meetArgs).getNormalizedDomain();
856	            if (instanceHolding(g, meet, true) == null) return false;
857	            for (Overload o : all) {
858	                if (o == o1 || o == o2 || o instanceof Overload.MethodOverload) continue;
859	                SingleFcn h = o.getFn();
860	                List<FType> hd = o.getParams();
861	                if (hd.size() != meet.size() || hasRest(hd)) continue;
862	                boolean holds;
863	                if (ownGeneric(h)) holds = instanceHolding(h, meet, true) != null;
864	                else if (!(h instanceof GenericFunctionOrMethod)) holds = FTypeTuple.make(meet).subtypeOf(FTypeTuple.make(hd));
865	                else continue;
866	                if (holds && declaredBelow(h, null, f, null, true) && declaredBelow(h, null, g, null, true)) {
867	                    return true;
868	                }
869	            }
870	            return false;
871	        }
872	        catch (FortressException ex) {
873	            return false;
874	        }
875	        catch (EmptyLatticeIntervalError ex) {
876	            return false;
877	        }
878	    }
