880	    /**
881	     * The static arguments of f at the overlap of f and g, whose symbolic
882	     * static arguments fArgs and gArgs the classes of parent match: each of
883	     * f's that matches a type that is no static parameter, that type; each
884	     * class of two type parameters or more, one type parameter made afresh,
885	     * whose bounds are every bound of each, each read in an environment where
886	     * its declaration's static parameters stand for their arguments at the
887	     * overlap, as createSymbolicInstantiation reads a declaration's bounds;
888	     * any other static parameter of f, itself.  Null where a class holds two
889	     * different types.
890	     */
891	    static private List<FType> meetParams(FGenericFunction f, List<FType> fArgs, FGenericFunction g,
892	                                          List<FType> gArgs, Map<FType, FType> parent, HasAt atF, HasAt atG) {
893	        Map<FType, List<FType>> classes = new IdentityHashMap<FType, List<FType>>();
894	        for (FType t : new ArrayList<FType>(parent.keySet())) {
895	            FType r = root(t, parent);
896	            List<FType> c = classes.get(r);
897	            if (c == null) classes.put(r, c = new ArrayList<FType>());
898	            c.add(t);
899	        }
900	        Map<FType, StaticParam> declOf = new IdentityHashMap<FType, StaticParam>();
901	        Map<FType, Boolean> ofF = new IdentityHashMap<FType, Boolean>();
902	        List<StaticParam> fps = f.getStaticParams();
903	        List<StaticParam> gps = g.getStaticParams();
904	        for (int i = 0; i < fArgs.size(); i++) {
905	            declOf.put(fArgs.get(i), fps.get(i));
906	            ofF.put(fArgs.get(i), true);
907	        }
908	        for (int j = 0; j < gArgs.size(); j++) {
909	            declOf.put(gArgs.get(j), gps.get(j));
910	            ofF.put(gArgs.get(j), false);
911	        }
912	        Environment geF = f.getWithin().extendAt(atF);
913	        Environment geG = g.getWithin().extendAt(atG);
914	        Map<FType, FType> valueOf = new IdentityHashMap<FType, FType>();
915	        Map<FType, List<FType>> made = new IdentityHashMap<FType, List<FType>>();
916	        for (Map.Entry<FType, List<FType>> e : classes.entrySet()) {
917	            FType ground = null;
918	            List<FType> params = new ArrayList<FType>();
919	            for (FType t : e.getValue()) {
920	                if (t instanceof SymbolicType && declOf.containsKey(t)) params.add(t);
921	                else if (t.isSymbolic()) continue;
922	                else if (ground == null) ground = t;
923	                else if (!ground.equals(t)) return null;
924	            }
925	            FType v;
926	            if (ground != null) v = ground;
927	            else if (params.size() >= 2) {
928	                StaticParam sp = declOf.get(params.get(0));
929	                v = new SymbolicInstantiatedType(NodeUtil.getName(sp), geF, sp);
930	                made.put(v, params);
931	            } else continue;
932	            for (FType t : e.getValue()) valueOf.put(t, v);
933	        }
934	        List<FType> meetArgs = new ArrayList<FType>(fArgs.size());
935	        for (int i = 0; i < fArgs.size(); i++) {
936	            FType a = fArgs.get(i);
937	            FType v = valueOf.containsKey(a) ? valueOf.get(a) : a;
938	            meetArgs.add(v);
939	            geF.putType(NodeUtil.getName(fps.get(i)), v);
940	        }
941	        for (int j = 0; j < gArgs.size(); j++) {
942	            FType a = gArgs.get(j);
943	            geG.putType(NodeUtil.getName(gps.get(j)), valueOf.containsKey(a) ? valueOf.get(a) : a);
944	        }
945	        Map<FType, List<FType>> bounds = new IdentityHashMap<FType, List<FType>>();
946	        for (Map.Entry<FType, List<FType>> e : made.entrySet()) {
947	            List<FType> bs = new ArrayList<FType>();
948	            for (FType p : e.getValue()) {
949	                StaticParam sp = declOf.get(p);
950	                EvalType et = new EvalType(ofF.get(p) ? geF : geG);
951	                for (FType b : et.getFTypeListFromList(sp.getExtendsClause())) {
952	                    if (b != FTypeTop.ONLY && !bs.contains(b)) bs.add(b);
953	                }
954	            }
955	            bounds.put(e.getKey(), bs);
956	        }
957	        for (Map.Entry<FType, List<FType>> e : bounds.entrySet()) {
958	            ((SymbolicInstantiatedType) e.getKey()).setExtendsAndExcludes(e.getValue(), null);
959	        }
960	        return meetArgs;
961	    }
