963	    /**
964	     * Match the parameter types a and b of two own generics, each over its
965	     * own static parameters: equal types; a static parameter against any
966	     * type, the two put in one class of parent; or instances of one generic
967	     * type whose static arguments match so.  False for any other pair.
968	     */
969	    static private boolean matchApart(FType a, FType b, Map<FType, FType> parent) {
970	        if (a == b) return true;
971	        if (a instanceof SymbolicType || b instanceof SymbolicType || a instanceof SymbolicNat
972	            || b instanceof SymbolicNat) {
973	            FType ra = root(a, parent);
974	            FType rb = root(b, parent);
975	            if (ra != rb) parent.put(ra, rb);
976	            return true;
977	        }
978	        if (a instanceof GenericTypeInstance && b instanceof GenericTypeInstance && sameGeneric(a, b)) {
979	            List<FType> xa = ((GenericTypeInstance) a).getTypeParams();
980	            List<FType> xb = ((GenericTypeInstance) b).getTypeParams();
981	            if (xa.size() != xb.size()) return false;
982	            for (int i = 0; i < xa.size(); i++) {
983	                if (!matchApart(xa.get(i), xb.get(i), parent)) return false;
984	            }
985	            return true;
986	        }
987	        return !mentionsSymbolic(a) && !mentionsSymbolic(b) && a.equals(b);
988	    }
