990	    /** The representative of t's class in parent, t itself where t is in none. */
991	    static private FType root(FType t, Map<FType, FType> parent) {
992	        if (!parent.containsKey(t)) parent.put(t, t);
993	        FType r = t;
994	        while (parent.get(r) != r) r = parent.get(r);
995	        return r;
996	    }
