998	    /**
999	     * The parameter types of the own generic o2 over static parameters of
1000	     * its own, apart from o1's (domain): o2's declared domain, unless o1 and
1001	     * o2 share their symbolic static arguments (shared), as two generic
1002	     * functions of one name and one list of static parameters do
1003	     * (GenericComparer), when it is o2 at symbolic static arguments made
1004	     * afresh (fresh).
1005	     */
1006	    static private final class Apart {
1007	        final List<FType> shared;
1008	        final List<FType> fresh;
1009	        final List<FType> domain;
1010	
1011	        private Apart(List<FType> shared, List<FType> fresh, List<FType> domain) {
1012	            this.shared = shared;
1013	            this.fresh = fresh;
1014	            this.domain = domain;
1015	        }
1016	
1017	        static Apart of(Overload o1, Overload o2) {
1018	            SingleFcn f = o1.getFn();
1019	            SingleFcn g = o2.getFn();
1020	            Apart declared = new Apart(null, null, o2.getParams());
1021	            if (!(f instanceof GenericFunctionOrMethod) || !(g instanceof FGenericFunction)) return declared;
1022	            GenericFunctionOrMethod gg = (GenericFunctionOrMethod) g;
1023	            if (GenericFunctionOrMethod.genComparer.compare((GenericFunctionOrMethod) f, gg) != 0) return declared;
1024	            List<FType> shared = GenericFunctionOrMethod.FunctionsAndState.symbolicStaticsByPartition.get(gg);
1025	            if (shared == null) return declared;
1026	            FGenericFunction fg = (FGenericFunction) g;
1027	            FnDecl d = fg.getFnDecl();
1028	            List<FType> fresh = SingleFcn.createSymbolicInstantiation(fg.getWithin(), NodeUtil.getStaticParams(d),
1029	                                                                      NodeUtil.getWhereClause(d), d);
1030	            return new Apart(shared, fresh, fg.typeApply(fresh, d).getNormalizedDomain());
1031	        }
1032	    }
