1034	    /**
1035	     * Whether a and b, parameter types of two own generics, are instances of
1036	     * one generic type, one of them over a static parameter, whose static
1037	     * arguments may be equal at some instance of each (mayBeEqual): some
1038	     * value then has both types.
1039	     */
1040	    static private boolean instancesMayCoincide(FType a, FType b) {
1041	        if (!(a instanceof GenericTypeInstance) || !(b instanceof GenericTypeInstance) || !sameGeneric(a, b)) {
1042	            return false;
1043	        }
1044	        if (!mentionsSymbolic(a) && !mentionsSymbolic(b)) return false;
1045	        return argsMayBeEqual(((GenericTypeInstance) a).getTypeParams(), ((GenericTypeInstance) b).getTypeParams());
1046	    }
1047	
1048	    /**
1049	     * Whether a and b, parameter types of two own generics, each over its own
1050	     * static parameters (b read through apart), exclude at every instance of
1051	     * each.  Instances of one generic type, one of them over a static
1052	     * parameter, exclude where their static arguments cannot be equal, since
1053	     * no type extends two instances of one generic type.  Any other pair
1054	     * excludes as excludesOther reads it; or, where the two declarations
1055	     * share their symbolic static arguments, where it excluded read at that
1056	     * one instantiation and every value of both a and b has it
1057	     * (oneInstance).
1058	     */
1059	    static private boolean excludesOverInstances(FType a, FType b, Apart apart) {
1060	        if (a instanceof GenericTypeInstance && b instanceof GenericTypeInstance && sameGeneric(a, b)
1061	            && (mentionsSymbolic(a) || mentionsSymbolic(b))) {
1062	            return !argsMayBeEqual(((GenericTypeInstance) a).getTypeParams(),
1063	                                   ((GenericTypeInstance) b).getTypeParams());
1064	        }
1065	        if (a.excludesOther(b)) return true;
1066	        return apart.fresh != null && oneInstance(a, b, apart);
1067	    }
1068	
1069	    /**
1070	     * Whether a value of both a, over the shared symbolic static arguments,
1071	     * and b, over the fresh ones, has the shared instance of b: each generic
1072	     * type that both extend is extended at one instance only, so the static
1073	     * arguments of its two instances match (matchApart), and that puts each
1074	     * fresh static argument b mentions with its shared one.  True too where
1075	     * two such instances cannot match: no value has both types.
1076	     */
1077	    static private boolean oneInstance(FType a, FType b, Apart apart) {
1078	        Map<FType, FType> parent = new IdentityHashMap<FType, FType>();
1079	        for (FType t1 : withSupertypes(a)) {
1080	            if (!(t1 instanceof GenericTypeInstance)) continue;
1081	            for (FType t2 : withSupertypes(b)) {
1082	                if (!(t2 instanceof GenericTypeInstance) || !sameGeneric(t1, t2)) continue;
1083	                if (!matchApart(t1, t2, parent)) return true;
1084	            }
1085	        }
1086	        for (int i = 0; i < apart.fresh.size(); i++) {
1087	            FType x = apart.fresh.get(i);
1088	            if (!mentions(b, x)) continue;
1089	            if (root(x, parent) != root(apart.shared.get(i), parent)) return false;
1090	        }
1091	        return true;
1092	    }
1093	
1094	    /** The type t, then every type it extends. */
1095	    static private List<FType> withSupertypes(FType t) {
1096	        List<FType> l = new ArrayList<FType>();
1097	        l.add(t);
1098	        l.addAll(t.getTransitiveExtends());
1099	        return l;
